(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = {};

  // ① 建卍解项目并贴代码
  const nameInput = document.querySelector('.tb-card .tb-input');
  if (!nameInput) return JSON.stringify({ error: '新建面板没打开' });
  setV(nameInput, '卍解测试·避障车');
  [...document.querySelectorAll('.tb-diff-opt')].find((b) => b.textContent.includes('卍解'))?.click();
  await sleep(300);
  [...document.querySelectorAll('.tb-btn-primary')].find((b) => b.textContent.includes('创建'))?.click();
  await sleep(3600);
  [...document.querySelectorAll('.pc-btn')].find((b) => b.textContent.includes('直接贴代码'))?.click();
  await sleep(600);
  const inputs = [...document.querySelectorAll('.pc-input')];
  setV(inputs[0], 'car.ino');
  setV(inputs[1], '主程序');
  setV(document.querySelector('.pc-textarea'), 'void loop() {\n  digitalWrite(9, HIGH);\n}\n');
  [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('放进作品'))?.click();
  await sleep(2200);
  out.saved = document.querySelector('.pc-item-name')?.textContent || null;

  // ② 回列表，点第一张卡的「做同款」（刚建的作品排在最前）
  document.querySelector('.pj-crumb-link')?.click();
  await sleep(2200);
  const firstCard = document.querySelector('.tb-project-main');
  out.firstCardName = (firstCard?.innerText || '').split('\n')[0];
  out.firstCardHasBadge = (firstCard?.innerText || '').includes('卍解');
  out.firstCardHasCodeTag = (firstCard?.innerText || '').includes('段代码');
  const remixBtn = [...document.querySelectorAll('.tb-project-actions .tb-mini')].find((b) => b.textContent.includes('做同款'));
  out.remixBtnFound = !!remixBtn;
  remixBtn?.click();
  await sleep(3600);
  out.afterRemixTitle = document.querySelector('.pj-title')?.textContent || null;
  out.remixDiffBadge = document.querySelector('.pj-diff')?.textContent || null;
  out.remixHasCodePanel = !!document.querySelector('.pc-wrap');
  out.remixCodeFile = document.querySelector('.pc-item-name')?.textContent || null;
  out.remixCodeVisible = (document.querySelector('.pc-code')?.textContent || '').includes('digitalWrite(9, HIGH)');

  const projects = await s.listProjects();
  const copy = projects.find((x) => x.name.includes('我的副本'));
  out.copyDifficulty = copy?.difficulty;
  out.copyCodeCount = copy?.codeCount;
  return JSON.stringify(out);
})()
